72	static int entropy_func(void* data, unsigned char* output, size_t len)
73	{
74	    (void)data;
75	    if (agent_secure_random(output, len) == 0) {
76	        return 0;
77	    }
78	    syslog(LOG_ERR, "[node_client] CRITICAL: No secure entropy source available\n");
79	    return -1; /* Generic error - TLS handshake will fail safely */
