83	
84	static int raw_read(node_ws_t* ws, void* buf, size_t len)
85	{
86	    if (ws->use_tls) {
87	        int n;
88	        do {
89	            n = mbedtls_ssl_read(&ws->ssl, buf, len);
90	        } while (n == MBEDTLS_ERR_SSL_WANT_READ);
91	        return n;
92	    }
93	    return (int)recv(ws->fd, buf, len, 0);
94	}
95	
96	static int raw_write(node_ws_t* ws, const void* buf, size_t len)
97	{
98	    if (ws->use_tls) {
99	        size_t written = 0;
100	        while (written < len) {
101	            int n = mbedtls_ssl_write(&ws->ssl, (const unsigned char*)buf + written,
102	                len - written);
103	            if (n == MBEDTLS_ERR_SSL_WANT_WRITE)
104	                continue;
105	            if (n <= 0)
106	                return -1;
107	            written += (size_t)n;
108	        }
109	        return (int)written;
110	    }
111	    return (int)send(ws->fd, buf, len, 0);
112	}
