114	static int read_exact(node_ws_t* ws, void* buf, size_t len)
115	{
116	    size_t total = 0;
117	    while (total < len) {
118	        int n = raw_read(ws, (char*)buf + total, len - total);
119	        if (n <= 0)
120	            return -1;
121	        total += (size_t)n;
122	    }
123	    return (int)total;
124	}
