126	/* ── WebSocket frame send (masked, as client) ──────────────── */
127	
128	static int ws_send_text(node_ws_t* ws, const char* data, size_t len)
129	{
130	    pthread_mutex_lock(&s_mutex);
131	    if (!ws->connected) {
132	        pthread_mutex_unlock(&s_mutex);
133	        return -1;
134	    }
135	
136	    int result = -1;
137	    uint8_t header[14];
138	    int hlen = 0;
139	    header[hlen++] = 0x81; /* FIN + text */
140	
141	    if (len < 126) {
142	        header[hlen++] = (uint8_t)(0x80 | len);
143	    } else if (len < 65536) {
144	        header[hlen++] = 0x80 | 126;
145	        header[hlen++] = (uint8_t)((len >> 8) & 0xFF);
146	        header[hlen++] = (uint8_t)(len & 0xFF);
147	    } else {
148	        header[hlen++] = 0x80 | 127;
149	        for (int i = 7; i >= 0; i--)
150	            header[hlen++] = (uint8_t)((len >> (i * 8)) & 0xFF);
151	    }
152	
153	    uint8_t mask[4];
154	    if (entropy_func(NULL, mask, 4) != 0)
155	        goto out;
156	    header[hlen++] = mask[0];
157	    header[hlen++] = mask[1];
158	    header[hlen++] = mask[2];
159	    header[hlen++] = mask[3];
160	
161	    if (raw_write(ws, header, hlen) < 0)
162	        goto out;
163	
164	    const uint8_t* src = (const uint8_t*)data;
165	    uint8_t chunk[256];
166	    for (size_t off = 0; off < len;) {
167	        size_t todo = len - off;
168	        if (todo > sizeof(chunk))
169	            todo = sizeof(chunk);
170	        for (size_t i = 0; i < todo; i++)
171	            chunk[i] = src[off + i] ^ mask[(off + i) & 3];
172	        if (raw_write(ws, chunk, todo) < 0)
173	            goto out;
174	        off += todo;
175	    }
176	    result = 0;
177	
178	out:
179	    pthread_mutex_unlock(&s_mutex);
180	    return result;
181	}
