185	static void gen_id(char* buf, size_t cap)
186	{
187	    unsigned char rnd[6];
188	    if (agent_secure_random(rnd, sizeof(rnd)) == 0) {
189	        snprintf(buf, cap, "%02x%02x%02x%02x-%02x%02x",
190	            rnd[0], rnd[1], rnd[2], rnd[3], rnd[4], rnd[5]);
191	    } else {
192	        /* Fallback: use address + time as unique-ish ID (not for crypto) */
193	        snprintf(buf, cap, "%08lx-%04x", (unsigned long)time(NULL),
194	            (unsigned)((uintptr_t)buf & 0xFFFF));
195	    }
196	}
