282	
283	static void handle_invoke(cJSON* payload)
284	{
285	    const char* invoke_id = cJSON_GetStringValue(cJSON_GetObjectItem(payload, "id"));
286	    const char* node_id = cJSON_GetStringValue(cJSON_GetObjectItem(payload, "nodeId"));
287	    const char* command = cJSON_GetStringValue(cJSON_GetObjectItem(payload, "command"));
288	
289	    cJSON* params_item = cJSON_GetObjectItem(payload, "paramsJSON");
290	    const char* params_json = cJSON_GetStringValue(params_item);
291	    if (!params_json) {
292	        cJSON* fallback = params_item;
293	        if (!fallback || !cJSON_IsObject(fallback))
294	            fallback = cJSON_GetObjectItem(payload, "params");
295	        if (fallback && cJSON_IsObject(fallback)) {
296	            params_json = cJSON_GetStringValue(fallback);
297	        }
298	    }
299	
300	    if (!invoke_id || !command)
301	        return;
302	
303	    syslog(LOG_DEBUG, "[%s] invoke: %s (id=%.8s)\n", TAG, command, invoke_id);
304	
305	    /* Execute via tool_registry */
306	    char* output = malloc(NODE_TOOL_OUTPUT_SIZE);
307	    if (!output)
308	        return;
309	
310	    output[0] = '\0';
311	    int ret = tool_registry_execute(command, params_json ? params_json : "{}",
312	        output, NODE_TOOL_OUTPUT_SIZE);
313	
314	    syslog(LOG_DEBUG, "[%s] tool_registry_execute(%s) ret=%d\n", TAG,
315	        command, ret);
316	
317	    /* Build result */
318	    cJSON* res_params = cJSON_CreateObject();
319	    cJSON_AddStringToObject(res_params, "id", invoke_id);
320	    if (node_id)
321	        cJSON_AddStringToObject(res_params, "nodeId", node_id);
322	    cJSON_AddBoolToObject(res_params, "ok", ret == OK);
323	
324	    if (ret == OK) {
325	        cJSON_AddStringToObject(res_params, "payloadJSON", output);
326	    } else {
327	        cJSON* err = cJSON_CreateObject();
328	        cJSON_AddStringToObject(err, "code", "COMMAND_ERROR");
329	        cJSON_AddStringToObject(err, "message",
330	            output[0] ? output : "tool execution failed");
331	        cJSON_AddItemToObject(res_params, "error", err);
332	    }
333	
334	    send_json_request("node.invoke.result", res_params);
335	    free(output);
336	}
