552	
553	static int ov_http_post(const agent_http_request_t *request,
554	                         agent_http_response_t *response,
555	                         void *user_data)
556	{
557	    ov_tls_ctx_t ctx;
558	    int ret;
559	
560	    (void)user_data;
561	
562	    if (!request || !response || !response->body || response->body_size == 0u ||
563	        !request->host || !request->path || !request->port) {
564	        return AGENT_ERROR_INVALID;
565	    }
566	
567	    memset(&ctx, 0, sizeof(ctx));
568	
569	    ov_tls_diag("http_post %s %s:%s%s body=%zu resp_cap=%zu timeout=%u",
570	                request->method ? request->method : "POST",
571	                request->host,
572	                request->port,
573	                request->path,
574	                request->body_size,
575	                response->body_size,
576	                request->timeout_ms);
577	
578	    ret = ov_tls_connect(&ctx, request->host, request->port, request->timeout_ms);
579	    if (ret != AGENT_OK) {
580	        ov_tls_diag("http_post connect failed err=%d", ret);
581	        ov_tls_ctx_free(&ctx);
582	        return ret;
583	    }
584	
585	    ret = ov_tls_write_request(&ctx,
586	                                request->method ? request->method : "POST",
587	                                request->host,
588	                                request->path,
589	                                request->headers,
590	                                (const char *)request->body,
591	                                request->body_size);
592	    if (ret != AGENT_OK) {
593	        ov_tls_diag("http_post write failed err=%d", ret);
594	        ov_tls_ctx_free(&ctx);
595	        return ret;
596	    }
597	
598	    size_t body_len = 0;
599	    int http_status = ov_tls_read_response(&ctx,
600	                                            response->body,
601	                                            response->body_size,
602	                                            &body_len);
603	
604	    ov_tls_ctx_free(&ctx);
605	
606	    if (http_status < 0) {
607	        ov_tls_diag("http_post read failed err=%d", http_status);
608	        return http_status;
609	    }
610	
611	    response->status_code = http_status;
612	    response->bytes_written = body_len;
613	    ov_tls_diag("http_post done status=%d body_len=%zu", http_status, body_len);
614	    if (http_status < 200 || http_status >= 300) {
615	        ov_tls_diag("http_post error body: %.300s",
616	                    response->body ? response->body : "(null)");
617	    }
618	
619	    return AGENT_OK;
620	}
