67	/* ── WS frame write lock ──────────────────────────────────── */
68	/* Protects ws_send_text_to_fd() from concurrent callers.
69	 * Without this, parallel tool threads invoking the same node
70	 * interleave header + payload bytes on the fd, corrupting the
71	 * WebSocket frame stream and causing the remote side to see
72	 * garbled data (observed as "JSON parse failed" + disconnect). */
73	
74	static pthread_mutex_t s_ws_write_mtx = PTHREAD_MUTEX_INITIALIZER;
75	
76	/* ── WS frame send (server→client, no mask) ────────────────── */
77	
78	static int ws_send_text_to_fd(int fd, const char* data, size_t len)
79	{
80	    unsigned char hdr[10];
81	    int hdr_len = 0;
82	
83	    hdr[0] = 0x81; /* FIN + text */
84	    if (len < 126) {
85	        hdr[1] = (unsigned char)len;
86	        hdr_len = 2;
87	    } else if (len < 65536) {
88	        hdr[1] = 126;
89	        hdr[2] = (unsigned char)(len >> 8);
90	        hdr[3] = (unsigned char)(len & 0xFF);
91	        hdr_len = 4;
92	    } else {
93	        return -1;
94	    }
95	
96	    pthread_mutex_lock(&s_ws_write_mtx);
97	    int ret = 0;
98	
99	    if (send(fd, hdr, hdr_len, 0) != hdr_len) {
100	        ret = -1;
101	    } else if (send(fd, data, len, 0) != (int)len) {
102	        ret = -1;
103	    }
104	
105	    pthread_mutex_unlock(&s_ws_write_mtx);
106	    return ret;
107	}
