111	static void gen_id(char* buf, size_t cap)
112	{
113	    unsigned char rnd[4];
114	    if (agent_secure_random(rnd, sizeof(rnd)) == 0) {
115	        snprintf(buf, cap, "%02x%02x%02x%02x-%04x",
116	            rnd[0], rnd[1], rnd[2], rnd[3],
117	            (unsigned)((rnd[0] << 8) | rnd[1]) & 0xFFFF);
118	    } else {
119	        /* Fallback: use address + time as unique-ish ID (not for crypto) */
120	        snprintf(buf, cap, "%08lx-%04x", (unsigned long)time(NULL),
121	            (unsigned)((uintptr_t)buf & 0xFFFF));
122	    }
123	}
