236	
237	static void handle_connect(int ws_fd, const char* req_id, cJSON* params)
238	{
239	    cJSON* client = cJSON_GetObjectItem(params, "client");
240	    const char* node_id = cJSON_GetStringValue(cJSON_GetObjectItem(client, "id"));
241	    const char* display = cJSON_GetStringValue(cJSON_GetObjectItem(client, "displayName"));
242	    const char* platform = cJSON_GetStringValue(cJSON_GetObjectItem(client, "platform"));
243	    const char* family = cJSON_GetStringValue(cJSON_GetObjectItem(client, "deviceFamily"));
244	
245	    if (!node_id || !node_id[0]) {
246	        cJSON* err = cJSON_CreateObject();
247	        cJSON_AddStringToObject(err, "code", "INVALID_CLIENT");
248	        cJSON_AddStringToObject(err, "message", "missing client.id");
249	        send_response(ws_fd, req_id, false, NULL, err);
250	        return;
251	    }
252	
253	    /* Sanitize node_id early so reconnect lookup matches stored id */
254	    char safe_id[NODE_ID_LEN];
255	    strncpy(safe_id, node_id, NODE_ID_LEN - 1);
256	    safe_id[NODE_ID_LEN - 1] = '\0';
257	    sanitize_tool_name_part(safe_id);
258	
259	    pthread_mutex_lock(&s_mtx);
260	
261	    /* Check for duplicate — replace if same id reconnects */
262	    node_entry_t* existing = find_node_by_id(safe_id);
263	    if (existing) {
264	        syslog(LOG_INFO, "[%s] Node %s reconnected (old fd=%d, new fd=%d)\n", TAG,
265	            node_id, existing->ws_fd, ws_fd);
266	        existing->ws_fd = ws_fd;
267	    }
268	
269	    node_entry_t* node = existing;
270	    if (!node) {
271	        /* Find free slot */
272	        for (int i = 0; i < NODE_MAX_NODES; i++) {
273	            if (!s_nodes[i].active) {
274	                node = &s_nodes[i];
275	                break;
276	            }
277	        }
278	    }
279	
280	    if (!node) {
281	        pthread_mutex_unlock(&s_mtx);
282	        cJSON* err = cJSON_CreateObject();
283	        cJSON_AddStringToObject(err, "code", "MAX_NODES");
284	        cJSON_AddStringToObject(err, "message", "node limit reached");
285	        send_response(ws_fd, req_id, false, NULL, err);
286	        return;
287	    }
288	
289	    memset(node, 0, sizeof(*node));
290	    node->active = true;
291	    node->ws_fd = ws_fd;
292	    strncpy(node->node_id, safe_id, NODE_ID_LEN - 1);
293	    if (display)
294	        strncpy(node->display_name, display, sizeof(node->display_name) - 1);
295	    if (platform)
296	        strncpy(node->platform, platform, sizeof(node->platform) - 1);
297	    if (family)
298	        strncpy(node->device_family, family, sizeof(node->device_family) - 1);
299	
300	    /* Parse commands */
301	    cJSON* cmds = cJSON_GetObjectItem(params, "commands");
302	    if (cmds && cJSON_IsArray(cmds)) {
303	        cJSON* c = NULL;
304	        cJSON_ArrayForEach(c, cmds)
305	        {
306	            if (node->cmd_count >= NODE_MAX_COMMANDS)
307	                break;
308	            if (cJSON_IsString(c)) {
309	                strncpy(node->commands[node->cmd_count], c->valuestring,
310	                    NODE_CMD_LEN - 1);
311	                sanitize_tool_name_part(node->commands[node->cmd_count]);
312	                node->cmd_count++;
313	            }
314	        }
315	    }
316	
317	    pthread_mutex_unlock(&s_mtx);
318	
319	    syslog(LOG_INFO, "[%s] Node connected: %s (%s/%s) with %d commands\n", TAG,
320	        node_id, platform ? platform : "?", family ? family : "?",
321	        node->cmd_count);
322	
323	    /* Node tools changed — mark registry dirty for rebuild */
324	    tool_registry_invalidate();
325	
326	    /* Send hello-ok */
327	    cJSON* payload = cJSON_CreateObject();
328	    cJSON_AddStringToObject(payload, "type", "hello-ok");
329	    cJSON* server = cJSON_CreateObject();
330	    char conn_id[32];
331	    gen_id(conn_id, sizeof(conn_id));
332	    cJSON_AddStringToObject(server, "connId", conn_id);
333	    cJSON_AddItemToObject(payload, "server", server);
334	    send_response(ws_fd, req_id, true, payload, NULL);
335	
336	    /* Rebuild tools JSON so the LLM sees the new node commands */
337	    tool_registry_rebuild_json();
338	}
