342	static void handle_invoke_result(cJSON* params)
343	{
344	    const char* invoke_id = cJSON_GetStringValue(cJSON_GetObjectItem(params, "id"));
345	    if (!invoke_id)
346	        return;
347	
348	    pending_invoke_t* p = find_pending(invoke_id);
349	    if (!p) {
350	        syslog(LOG_WARNING, "[%s] No pending invoke for id=%s\n", TAG, invoke_id);
351	        return;
352	    }
353	
354	    pthread_mutex_lock(&p->mtx);
355	    p->ok = cJSON_IsTrue(cJSON_GetObjectItem(params, "ok"));
356	
357	    if (p->ok) {
358	        const char* pj = cJSON_GetStringValue(cJSON_GetObjectItem(params, "payloadJSON"));
359	        if (pj)
360	            p->result_json = strdup(pj);
361	    } else {
362	        cJSON* err = cJSON_GetObjectItem(params, "error");
363	        const char* msg = cJSON_GetStringValue(cJSON_GetObjectItem(err, "message"));
364	        p->result_json = strdup(msg ? msg : "node error");
365	    }
366	
367	    p->done = true;
368	    pthread_cond_signal(&p->cond);
369	    pthread_mutex_unlock(&p->mtx);
370	}
