28	static int writer_putc(json_writer_t *writer, char c)
29	{
30	    if (!writer || !writer->buffer || writer->size == 0u) {
31	        return AGENT_ERROR_INVALID;
32	    }
33	    if (writer->used + 1u >= writer->size) {
34	        return AGENT_ERROR_LIMIT;
35	    }
36	
37	    writer->buffer[writer->used++] = c;
38	    writer->buffer[writer->used] = '\0';
39	    return AGENT_OK;
40	}
