42	static int writer_append(json_writer_t *writer, const char *text)
43	{
44	    size_t n;
45	
46	    if (!text) {
47	        return AGENT_OK;
48	    }
49	
50	    n = strlen(text);
51	    if (!writer || !writer->buffer || writer->used + n >= writer->size) {
52	        return AGENT_ERROR_LIMIT;
53	    }
54	
55	    memcpy(writer->buffer + writer->used, text, n);
56	    writer->used += n;
57	    writer->buffer[writer->used] = '\0';
58	    return AGENT_OK;
59	}
