61	static int writer_printf(json_writer_t *writer, const char *fmt, ...)
62	{
63	    va_list ap;
64	    int n;
65	
66	    if (!writer || !writer->buffer || writer->size == 0u) {
67	        return AGENT_ERROR_INVALID;
68	    }
69	    if (writer->used >= writer->size) {
70	        return AGENT_ERROR_LIMIT;
71	    }
72	
73	    va_start(ap, fmt);
74	    n = vsnprintf(writer->buffer + writer->used,
75	                  writer->size - writer->used,
76	                  fmt,
77	                  ap);
78	    va_end(ap);
79	
80	    if (n < 0) {
81	        return AGENT_ERROR;
82	    }
83	    if ((size_t)n >= writer->size - writer->used) {
84	        writer->buffer[writer->size - 1u] = '\0';
85	        return AGENT_ERROR_LIMIT;
86	    }
87	
88	    writer->used += (size_t)n;
89	    return AGENT_OK;
90	}
