92	static int writer_append_json_string(json_writer_t *writer, const char *text)
93	{
94	    int ret = writer_putc(writer, '"');
95	
96	    if (ret != AGENT_OK) {
97	        return ret;
98	    }
99	
100	    if (text) {
101	        while (*text) {
102	            unsigned char c = (unsigned char)*text++;
103	            switch (c) {
104	            case '"':
105	                ret = writer_append(writer, "\\\"");
106	                break;
107	            case '\\':
108	                ret = writer_append(writer, "\\\\");
109	                break;
110	            case '\n':
111	                ret = writer_append(writer, "\\n");
112	                break;
113	            case '\r':
114	                ret = writer_append(writer, "\\r");
115	                break;
116	            case '\t':
117	                ret = writer_append(writer, "\\t");
118	                break;
119	            default:
120	                if (c < 0x20u) {
121	                    ret = writer_printf(writer, "\\u%04x", c);
122	                } else {
123	                    ret = writer_putc(writer, (char)c);
124	                }
125	                break;
126	            }
127	            if (ret != AGENT_OK) {
128	                return ret;
129	            }
130	        }
131	    }
132	
133	    return writer_putc(writer, '"');
134	}
