144	static bool is_hex4(const char *s)
145	{
146	    int i;
147	
148	    if (!s) {
149	        return false;
150	    }
151	
152	    for (i = 0; i < 4; i++) {
153	        if (!isxdigit((unsigned char)s[i])) {
154	            return false;
155	        }
156	    }
157	    return true;
158	}
