160	static const char *json_parse_value(const char *s, int depth);
161	
162	static const char *json_parse_string(const char *s)
163	{
164	    if (!s || *s != '"') {
165	        return NULL;
166	    }
167	
168	    s++;
169	    while (*s) {
170	        unsigned char c = (unsigned char)*s++;
171	
172	        if (c == '"') {
173	            return s;
174	        }
175	        if (c < 0x20u) {
176	            return NULL;
177	        }
178	        if (c == '\\') {
179	            char esc = *s++;
180	            switch (esc) {
181	            case '"':
182	            case '\\':
183	            case '/':
184	            case 'b':
185	            case 'f':
186	            case 'n':
187	            case 'r':
188	            case 't':
189	                break;
190	            case 'u':
191	                if (!is_hex4(s)) {
192	                    return NULL;
193	                }
194	                s += 4;
195	                break;
196	            default:
197	                return NULL;
198	            }
199	        }
200	    }
201	
202	    return NULL;
203	}
