205	static const char *json_parse_number(const char *s)
206	{
207	    if (!s) {
208	        return NULL;
209	    }
210	
211	    if (*s == '-') {
212	        s++;
213	    }
214	
215	    if (*s == '0') {
216	        s++;
217	    } else if (*s >= '1' && *s <= '9') {
218	        while (isdigit((unsigned char)*s)) {
219	            s++;
220	        }
221	    } else {
222	        return NULL;
223	    }
224	
225	    if (*s == '.') {
226	        s++;
227	        if (!isdigit((unsigned char)*s)) {
228	            return NULL;
229	        }
230	        while (isdigit((unsigned char)*s)) {
231	            s++;
232	        }
233	    }
234	
235	    if (*s == 'e' || *s == 'E') {
236	        s++;
237	        if (*s == '+' || *s == '-') {
238	            s++;
239	        }
240	        if (!isdigit((unsigned char)*s)) {
241	            return NULL;
242	        }
243	        while (isdigit((unsigned char)*s)) {
244	            s++;
245	        }
246	    }
247	
248	    return s;
249	}
