251	static const char *json_parse_array(const char *s, int depth)
252	{
253	    if (!s || *s != '[' || depth >= JSON_MAX_DEPTH) {
254	        return NULL;
255	    }
256	
257	    s = skip_ws(s + 1);
258	    if (*s == ']') {
259	        return s + 1;
260	    }
261	
262	    while (*s) {
263	        s = json_parse_value(s, depth + 1);
264	        if (!s) {
265	            return NULL;
266	        }
267	
268	        s = skip_ws(s);
269	        if (*s == ',') {
270	            s = skip_ws(s + 1);
271	            continue;
272	        }
273	        if (*s == ']') {
274	            return s + 1;
275	        }
276	        return NULL;
277	    }
278	
279	    return NULL;
280	}
281	
282	static const char *json_parse_object(const char *s, int depth)
283	{
284	    if (!s || *s != '{' || depth >= JSON_MAX_DEPTH) {
285	        return NULL;
286	    }
287	
288	    s = skip_ws(s + 1);
289	    if (*s == '}') {
290	        return s + 1;
291	    }
292	
293	    while (*s) {
294	        s = json_parse_string(s);
295	        if (!s) {
296	            return NULL;
297	        }
298	
299	        s = skip_ws(s);
300	        if (*s != ':') {
301	            return NULL;
302	        }
303	
304	        s = skip_ws(s + 1);
305	        s = json_parse_value(s, depth + 1);
306	        if (!s) {
307	            return NULL;
308	        }
309	
310	        s = skip_ws(s);
311	        if (*s == ',') {
312	            s = skip_ws(s + 1);
313	            continue;
314	        }
315	        if (*s == '}') {
316	            return s + 1;
317	        }
318	        return NULL;
319	    }
320	
321	    return NULL;
322	}
323	
324	static const char *json_parse_value(const char *s, int depth)
325	{
326	    s = skip_ws(s);
327	    if (!s || depth >= JSON_MAX_DEPTH) {
328	        return NULL;
329	    }
330	
331	    switch (*s) {
332	    case '"':
333	        return json_parse_string(s);
334	    case '{':
335	        return json_parse_object(s, depth);
336	    case '[':
337	        return json_parse_array(s, depth);
338	    case 't':
339	        return strncmp(s, "true", 4) == 0 ? s + 4 : NULL;
340	    case 'f':
341	        return strncmp(s, "false", 5) == 0 ? s + 5 : NULL;
342	    case 'n':
343	        return strncmp(s, "null", 4) == 0 ? s + 4 : NULL;
344	    default:
345	        if (*s == '-' || isdigit((unsigned char)*s)) {
346	            return json_parse_number(s);
347	        }
348	        return NULL;
349	    }
350	}
