352	static bool validate_schema_object(const char *schema)
353	{
354	    const char *s = skip_ws(schema);
355	    const char *end;
356	
357	    if (!s || *s == '\0') {
358	        return true;
359	    }
360	    if (*s != '{') {
361	        return false;
362	    }
363	
364	    end = json_parse_object(s, 0);
365	    if (!end) {
366	        return false;
367	    }
368	
369	    end = skip_ws(end);
370	    return *end == '\0';
371	}
