373	static int append_parameters(json_writer_t *writer, const char *schema)
374	{
375	    const char *trimmed = skip_ws(schema);
376	
377	    if (!trimmed || trimmed[0] == '\0') {
378	        return writer_append(writer,
379	                             "{\"type\":\"object\",\"properties\":{},"
380	                             "\"additionalProperties\":false}");
381	    }
382	
383	    if (!validate_schema_object(trimmed)) {
384	        return AGENT_ERROR_PARSE;
385	    }
386	
387	    return writer_append(writer, trimmed);
388	}
