390	static int build_schema_uncached(agent_t *agent,
391	                                 char *buffer,
392	                                 size_t buffer_size,
393	                                 size_t *written)
394	{
395	    json_writer_t writer;
396	    bool first = true;
397	    uint32_t i;
398	    int ret;
399	
400	    writer.buffer = buffer;
401	    writer.size = buffer_size;
402	    writer.used = 0u;
403	    buffer[0] = '\0';
404	
405	    ret = writer_putc(&writer, '[');
406	    if (ret != AGENT_OK) {
407	        return ret;
408	    }
409	
410	    for (i = 0u; i < agent->tool_count; i++) {
411	        const agent_tool_entry_t *entry = &agent->tools[i];
412	        const agent_tool_t *tool = &entry->def;
413	
414	        if (!agent_tool_entry_is_enabled(entry) ||
415	            !agent_tool_entry_is_llm_visible(entry)) {
416	            continue;
417	        }
418	
419	        if (!first) {
420	            ret = writer_putc(&writer, ',');
421	            if (ret != AGENT_OK) {
422	                return ret;
423	            }
424	        }
425	        first = false;
426	
427	        ret = writer_append(&writer, "{\"type\":\"function\",\"function\":{\"name\":");
428	        if (ret != AGENT_OK) {
429	            return ret;
430	        }
431	        ret = writer_append_json_string(&writer, tool->name);
432	        if (ret != AGENT_OK) {
433	            return ret;
434	        }
435	        ret = writer_append(&writer, ",\"description\":");
436	        if (ret != AGENT_OK) {
437	            return ret;
438	        }
439	        ret = writer_append_json_string(&writer,
440	                                        tool->description ? tool->description : "");
441	        if (ret != AGENT_OK) {
442	            return ret;
443	        }
444	        ret = writer_append(&writer, ",\"parameters\":");
445	        if (ret != AGENT_OK) {
446	            return ret;
447	        }
448	        ret = append_parameters(&writer, tool->input_schema_json);
449	        if (ret != AGENT_OK) {
450	            return ret;
451	        }
452	        ret = writer_append(&writer, "}}");
453	        if (ret != AGENT_OK) {
454	            return ret;
455	        }
456	    }
457	
458	    ret = writer_putc(&writer, ']');
459	    if (ret != AGENT_OK) {
460	        return ret;
461	    }
462	
463	    if (written) {
464	        *written = writer.used;
465	    }
466	    return AGENT_OK;
467	}
