479	static int copy_schema_cache(agent_t *agent,
480	                             char *buffer,
481	                             size_t buffer_size,
482	                             size_t *written)
483	{
484	    if (agent->tool_schema_cache_len + 1u > buffer_size) {
485	        if (buffer_size > 0u) {
486	            buffer[0] = '\0';
487	        }
488	        return AGENT_ERROR_LIMIT;
489	    }
490	
491	    memcpy(buffer, agent->tool_schema_cache, agent->tool_schema_cache_len + 1u);
492	    if (written) {
493	        *written = agent->tool_schema_cache_len;
494	    }
495	    return AGENT_OK;
496	}
497	
498	int agent_tool_schema_build(agent_t *agent,
499	                            char *buffer,
500	                            size_t buffer_size,
501	                            size_t *written)
502	{
503	    int ret;
504	    size_t cache_len = 0u;
505	
506	    if (!agent || !buffer || buffer_size == 0u) {
507	        return AGENT_ERROR_INVALID;
508	    }
509	
510	    if (!agent->tool_schema_dirty && agent->tool_schema_cache_len > 0u) {
511	        return copy_schema_cache(agent, buffer, buffer_size, written);
512	    }
513	
514	    ret = build_schema_uncached(agent,
515	                                agent->tool_schema_cache,
516	                                sizeof(agent->tool_schema_cache),
517	                                &cache_len);
518	    if (ret != AGENT_OK) {
519	        buffer[0] = '\0';
520	        return ret;
521	    }
522	
523	    agent->tool_schema_cache_len = cache_len;
524	    agent->tool_schema_dirty = false;
525	
526	    return copy_schema_cache(agent, buffer, buffer_size, written);
527	}
