/* SPDX-License-Identifier: Apache-2.0 */
/**
 * smart_home_config_store: 统一 JSON 配置存取模块。
 *
 * 通用骨架 + backends/settings/state 薄封装。
 * secrets.json 不在本模块（config/README：普通 store 不加载/回退/写回 secrets）。
 */

#include "smart_home_config_store.h"
#include "smart_home_backends.h"
#include "../device/smart_home_device.h"

#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

/* ── 通用骨架 ── */

#define CONFIG_STORE_VERSION 1
#define CONFIG_STORE_TMP_ATTEMPTS 16

static const char *config_error_str(int status)
{
    switch (status) {
    case AGENT_ERROR_NOMEM:   return "out of memory";
    case AGENT_ERROR_INVALID: return "invalid argument";
    case AGENT_ERROR_PARSE:   return "JSON parse error";
    case AGENT_ERROR_LIMIT:   return "limit exceeded";
    default:                  return "config error";
    }
}

static void set_error(char *error, size_t error_size, const char *message)
{
    if (error && error_size > 0u) {
        snprintf(error, error_size, "%s", message ? message : "config error");
    }
}

static int check_version(const cJSON *root, char *error, size_t error_size)
{
    const cJSON *version;

    if (!root || !cJSON_IsObject(root)) {
        set_error(error, error_size, "config is not a JSON object");
        return AGENT_ERROR_PARSE;
    }

    version = cJSON_GetObjectItemCaseSensitive(root, "version");
    if (!version || !cJSON_IsNumber(version)) {
        set_error(error, error_size, "missing integer version");
        return AGENT_ERROR_PARSE;
    }
    if (version->valueint != CONFIG_STORE_VERSION) {
        set_error(error, error_size, "unsupported version");
        return AGENT_ERROR_PARSE;
    }

    return AGENT_OK;
}

static cJSON *parse_default(const char *default_json,
                            char *error,
                            size_t error_size)
{
    cJSON *root;

    if (!default_json || !default_json[0]) {
        set_error(error, error_size, "no default available");
        return NULL;
    }

    root = cJSON_Parse(default_json);
    if (!root) {
        set_error(error, error_size, "default JSON broken");
        return NULL;
    }

    return root;
}

int smart_home_config_store_load(const char *path,
                                 const char *default_json,
                                 smart_home_config_validate_fn validate,
                                 void *user_data,
                                 cJSON **out_root,
                                 int *fell_back,
                                 char *error,
                                 size_t error_size)
{
    cJSON *root;
    char *text;
    long size;
    FILE *file;
    int ret;

    if (!path || !out_root) {
        return AGENT_ERROR_INVALID;
    }
    *out_root = NULL;
    if (fell_back) {
        *fell_back = 0;
    }

    file = fopen(path, "rb");
    if (!file) {
        /* 文件不存在 → 回退默认 */
        root = parse_default(default_json, error, error_size);
        if (!root) {
            return AGENT_ERROR_PARSE;
        }
        if (fell_back) {
            *fell_back = 1;
        }
        *out_root = root;
        return AGENT_OK;
    }

    if (fseek(file, 0, SEEK_END) != 0) {
        fclose(file);
        return AGENT_ERROR_INVALID;
    }
    size = ftell(file);
    if (size < 0 || size > (long)(CONFIG_STORE_MAX_FILE_SIZE)) {
        fclose(file);
        set_error(error, error_size, "file too large");
        return AGENT_ERROR_LIMIT;
    }
    if (fseek(file, 0, SEEK_SET) != 0) {
        fclose(file);
        return AGENT_ERROR_INVALID;
    }

    text = malloc((size_t)size + 1u);
    if (!text) {
        fclose(file);
        set_error(error, error_size, "out of memory");
        return AGENT_ERROR_NOMEM;
    }
    if (fread(text, 1u, (size_t)size, file) != (size_t)size) {
        fclose(file);
        free(text);
        set_error(error, error_size, "read failed");
        return AGENT_ERROR_PARSE;
    }
    text[size] = '\0';
    fclose(file);

    root = cJSON_Parse(text);
    free(text);
    if (!root) {
        /* 损坏 → 保留原文件,回退默认 */
        root = parse_default(default_json, error, error_size);
        if (!root) {
            return AGENT_ERROR_PARSE;
        }
        if (fell_back) {
            *fell_back = 1;
        }
        *out_root = root;
        return AGENT_OK;
    }

    ret = check_version(root, error, error_size);
    if (ret != AGENT_OK) {
        cJSON_Delete(root);
        root = parse_default(default_json, error, error_size);
        if (!root) {
            return AGENT_ERROR_PARSE;
        }
        if (fell_back) {
            *fell_back = 1;
        }
        *out_root = root;
        return AGENT_OK;
    }

    if (validate) {
        ret = validate(root, user_data);
        if (ret != AGENT_OK) {
            cJSON_Delete(root);
            set_error(error, error_size, config_error_str(ret));
            root = parse_default(default_json, error, error_size);
            if (!root) {
                return AGENT_ERROR_PARSE;
            }
            if (fell_back) {
                *fell_back = 1;
            }
            *out_root = root;
            return AGENT_OK;
        }
    }

    *out_root = root;
    return AGENT_OK;
}

static int write_all(int fd, const char *buffer, size_t size)
{
    size_t written = 0u;

    while (written < size) {
        ssize_t n = write(fd, buffer + written, size - written);
        if (n < 0) {
            if (errno == EINTR) {
                continue;
            }
            return -1;
        }
        written += (size_t)n;
    }

    return 0;
}

int smart_home_config_store_save(const char *path, const cJSON *root)
{
    char tmp_path[SMART_HOME_CONFIG_PATH_MAX];
    char *json;
    int fd;
    int attempt;
    int ret;

    if (!path || !root) {
        return AGENT_ERROR_INVALID;
    }

    json = cJSON_PrintUnformatted(root);
    if (!json) {
        return AGENT_ERROR_NOMEM;
    }

    /* 同目录、带唯一 generation 的临时文件,完整写入 + fsync 后原子 rename */
    for (attempt = 0; attempt < CONFIG_STORE_TMP_ATTEMPTS; attempt++) {
        struct timespec ts;
        unsigned long gen;

        clock_gettime(CLOCK_REALTIME, &ts);
        gen = (unsigned long)ts.tv_sec ^ ((unsigned long)ts.tv_nsec << 16);
        snprintf(tmp_path,
                 sizeof(tmp_path),
                 "%s.tmp%lu",
                 path,
                 gen);

        fd = open(tmp_path, O_WRONLY | O_CREAT | O_EXCL, 0640);
        if (fd >= 0) {
            break;
        }
        if (errno != EEXIST) {
            free(json);
            return AGENT_ERROR_PARSE;
        }
    }
    if (attempt >= CONFIG_STORE_TMP_ATTEMPTS) {
        free(json);
        return AGENT_ERROR_LIMIT;
    }

    ret = write_all(fd, json, strlen(json));
    free(json);
    if (ret != 0) {
        close(fd);
        unlink(tmp_path);
        return AGENT_ERROR_PARSE;
    }
    if (fsync(fd) != 0) {
        close(fd);
        unlink(tmp_path);
        return AGENT_ERROR_PARSE;
    }
    close(fd);

    if (rename(tmp_path, path) != 0) {
        unlink(tmp_path);
        return AGENT_ERROR_PARSE;
    }

    return AGENT_OK;
}

/* ── backends.json ── */

/* 编译期内置预设表即默认来源(config/README: 由该表构造内存默认值) */
static cJSON *backends_default_root(void)
{
    cJSON *root;
    cJSON *backends;
    size_t count;
    size_t i;

    root = cJSON_CreateObject();
    if (!root) {
        return NULL;
    }
    cJSON_AddNumberToObject(root, "version", CONFIG_STORE_VERSION);
    backends = cJSON_AddArrayToObject(root, "backends");
    if (!backends) {
        cJSON_Delete(root);
        return NULL;
    }

    count = smart_home_llm_backend_count();
    for (i = 0u; i < count; i++) {
        const smart_home_llm_backend_preset_t *preset =
            smart_home_llm_backend_get(i);
        cJSON *item;

        if (!preset) {
            continue;
        }
        item = cJSON_CreateObject();
        if (!item) {
            cJSON_Delete(root);
            return NULL;
        }
        cJSON_AddStringToObject(item, "backend_id", preset->id);
        cJSON_AddStringToObject(item, "label", preset->name);
        cJSON_AddStringToObject(item, "host", preset->host);
        cJSON_AddStringToObject(item, "path", preset->path);
        cJSON_AddStringToObject(item, "port", preset->port);
        cJSON_AddStringToObject(item, "default_model", preset->default_model);
        cJSON_AddNumberToObject(item, "default_timeout_ms",
                                (double)preset->default_timeout_ms);
        cJSON_AddItemToArray(backends, item);
    }

    return root;
}

static bool valid_backend_id(const char *id)
{
    const char *p;

    if (!id || !id[0] || strlen(id) > 32u) {
        return false;
    }
    for (p = id; *p; p++) {
        if (!((*p >= 'a' && *p <= 'z') ||
              (*p >= '0' && *p <= '9') ||
              *p == '_' || *p == '-')) {
            return false;
        }
    }

    return true;
}

static int validate_backends(const cJSON *root, void *user_data)
{
    const cJSON *backends;
    const cJSON *item;
    int count = 0;
    int i;

    (void)user_data;

    backends = cJSON_GetObjectItemCaseSensitive(root, "backends");
    if (!backends || !cJSON_IsArray(backends)) {
        return AGENT_ERROR_PARSE;
    }

    cJSON_ArrayForEach(item, backends) {
        const cJSON *id;

        if (!cJSON_IsObject(item)) {
            return AGENT_ERROR_PARSE;
        }
        id = cJSON_GetObjectItemCaseSensitive(item, "backend_id");
        if (!cJSON_IsString(id) || !valid_backend_id(id->valuestring)) {
            return AGENT_ERROR_PARSE;
        }
        count++;
    }

    if (count == 0 || count > CONFIG_SMART_HOME_MAX_BACKENDS) {
        return AGENT_ERROR_LIMIT;
    }

    /* backend_id 唯一性 */
    for (i = 0; i < count; i++) {
        const cJSON *a = cJSON_GetArrayItem(backends, i);
        const cJSON *aid = cJSON_GetObjectItemCaseSensitive(a, "backend_id");
        int j;

        for (j = i + 1; j < count; j++) {
            const cJSON *b = cJSON_GetArrayItem(backends, j);
            const cJSON *bid = cJSON_GetObjectItemCaseSensitive(b, "backend_id");
            if (aid->valuestring && bid->valuestring &&
                strcmp(aid->valuestring, bid->valuestring) == 0) {
                return AGENT_ERROR_INVALID;
            }
        }
    }

    return AGENT_OK;
}

static char *backends_default_json_string(void)
{
    cJSON *root;
    char *json;

    root = backends_default_root();
    if (!root) {
        return NULL;
    }
    json = cJSON_PrintUnformatted(root);
    cJSON_Delete(root);
    return json;
}

int smart_home_config_backends_load(cJSON **out_root,
                                    int *fell_back,
                                    char *error,
                                    size_t error_size)
{
    char *default_json;
    int ret;

    default_json = backends_default_json_string();
    if (!default_json) {
        return AGENT_ERROR_NOMEM;
    }
    ret = smart_home_config_store_load(SMART_HOME_CONFIG_BACKENDS_PATH,
                                       default_json,
                                       validate_backends,
                                       NULL,
                                       out_root,
                                       fell_back,
                                       error,
                                       error_size);
    free(default_json);
    return ret;
}

int smart_home_config_backends_save(const cJSON *root)
{
    return smart_home_config_store_save(SMART_HOME_CONFIG_BACKENDS_PATH, root);
}

/* ── settings.json ── */

static int validate_settings(const cJSON *root, void *user_data)
{
    const cJSON *active;

    (void)user_data;

    active = cJSON_GetObjectItemCaseSensitive(root, "active_backend_id");
    if (!cJSON_IsString(active) || active->valuestring[0] == '\0') {
        return AGENT_ERROR_PARSE;
    }
    if (!valid_backend_id(active->valuestring)) {
        return AGENT_ERROR_PARSE;
    }

    return AGENT_OK;
}

int smart_home_config_settings_load(cJSON **out_root,
                                    int *fell_back,
                                    char *error,
                                    size_t error_size)
{
    return smart_home_config_store_load(SMART_HOME_CONFIG_SETTINGS_PATH,
                                        "{\"version\":1,"
                                        "\"active_backend_id\":\"deepseek\"}",
                                        validate_settings,
                                        NULL,
                                        out_root,
                                        fell_back,
                                        error,
                                        error_size);
}

int smart_home_config_settings_save(const cJSON *root)
{
    return smart_home_config_store_save(SMART_HOME_CONFIG_SETTINGS_PATH, root);
}

/* ── state.json ── */

static int validate_state(const cJSON *root, void *user_data)
{
    const cJSON *devices;
    const cJSON *item;
    int count = 0;

    (void)user_data;

    devices = cJSON_GetObjectItemCaseSensitive(root, "devices");
    if (!devices || !cJSON_IsArray(devices)) {
        return AGENT_ERROR_PARSE;
    }
    if (cJSON_GetArraySize(devices) > SMART_HOME_MAX_DEVICES) {
        return AGENT_ERROR_LIMIT;
    }

    cJSON_ArrayForEach(item, devices) {
        const cJSON *id;
        const cJSON *type;

        if (!cJSON_IsObject(item)) {
            return AGENT_ERROR_PARSE;
        }
        id = cJSON_GetObjectItemCaseSensitive(item, "id");
        type = cJSON_GetObjectItemCaseSensitive(item, "type");
        if (!cJSON_IsNumber(id) || id->valueint <= 0) {
            return AGENT_ERROR_PARSE;
        }
        if (!cJSON_IsString(type)) {
            return AGENT_ERROR_PARSE;
        }
        count++;
    }

    return AGENT_OK;
}

static cJSON *state_default_root(void)
{
    /* 与 state.example.json 的 3 个设备保持一致 */
    return cJSON_Parse(
        "{\"version\":1,"
        "\"devices\":["
        "{\"id\":1,\"room\":\"living_room\",\"name\":\"Living Light\","
        "\"type\":\"light\",\"on\":false,\"brightness\":0},"
        "{\"id\":2,\"room\":\"bedroom\",\"name\":\"Bedroom Light\","
        "\"type\":\"light\",\"on\":false,\"brightness\":0},"
        "{\"id\":3,\"room\":\"bedroom\",\"name\":\"Bedroom AC\","
        "\"type\":\"ac\",\"on\":false,\"temperature\":26,"
        "\"mode\":\"cool\",\"fan_speed\":\"auto\"}],"
        "\"environment\":{\"temperature\":26,\"humidity\":45,"
        "\"ambient_light\":300}}");
}

int smart_home_config_state_load(cJSON **out_root,
                                 int *fell_back,
                                 char *error,
                                 size_t error_size)
{
    cJSON *default_root;
    char *default_json;
    int ret;

    default_root = state_default_root();
    if (!default_root) {
        return AGENT_ERROR_NOMEM;
    }
    default_json = cJSON_PrintUnformatted(default_root);
    cJSON_Delete(default_root);
    if (!default_json) {
        return AGENT_ERROR_NOMEM;
    }

    ret = smart_home_config_store_load(SMART_HOME_CONFIG_STATE_PATH,
                                       default_json,
                                       validate_state,
                                       NULL,
                                       out_root,
                                       fell_back,
                                       error,
                                       error_size);
    free(default_json);
    return ret;
}

int smart_home_config_state_save(const cJSON *root)
{
    return smart_home_config_store_save(SMART_HOME_CONFIG_STATE_PATH, root);
}

