/* SPDX-License-Identifier: Apache-2.0 */
/**
 * smart_home_config_store host 测试。
 *
 * 验证通用骨架（加载/回退/原子写/version）与 backends/settings/state 薄封装。
 * 使用临时目录作为 /data/smart_home，不碰真实设备文件。
 *
 * 构建（host gcc）：
 *   cc -o test_config_store test_config_store.c \
 *      ../src/config/smart_home_config_store.c \
 *      ../src/config/smart_home_backends.c \
 *      -I../src/config -I../src/agent -I../src/device -I../src/net \
 *      -I<path>/cJSON -DconfigTIME...  （cJSON 需链接）
 */

#include "smart_home_config_store.h"
#include "smart_home_backends.h"

#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

static char g_tmpdir[128];
static char g_backends_path[160];
static char g_settings_path[160];
static char g_state_path[160];

static void setup_temp_dir(void)
{
    snprintf(g_tmpdir, sizeof(g_tmpdir), "/tmp/smh_cfg_test_%ld",
             (long)getpid());
    mkdir(g_tmpdir, 0700);
    snprintf(g_backends_path, sizeof(g_backends_path),
             "%s/backends.json", g_tmpdir);
    snprintf(g_settings_path, sizeof(g_settings_path),
             "%s/settings.json", g_tmpdir);
    snprintf(g_state_path, sizeof(g_state_path),
             "%s/state.json", g_tmpdir);

    /* 让 store 的路径宏指向临时目录（测试用：路径宏在 header 里是编译期，
     * 这里通过重新定义路径实现隔离——实际使用用真实宏） */
    unlink(g_backends_path);
    unlink(g_settings_path);
    unlink(g_state_path);
}

static void cleanup_temp_dir(void)
{
    unlink(g_backends_path);
    unlink(g_settings_path);
    unlink(g_state_path);
    rmdir(g_tmpdir);
}

/* ── 用宏重映射路径（测试隔离，避免碰真实 /data） ── */
/* 说明：config_store.c 用 SMART_HOME_CONFIG_*_PATH 宏。为测试隔离，这里
 * 通过包含一个重定义头实现——见下方 test_config_store_paths.h。 */

#include "test_config_store_paths.h"

static void test_backends_missing_falls_back(void)
{
    cJSON *root = NULL;
    int fell_back = 0;
    char error[96];

    /* 文件不存在 → 回退内置默认（5 个预设） */
    assert(smart_home_config_backends_load(&root, &fell_back, error,
                                           sizeof(error)) == AGENT_OK);
    assert(root != NULL);
    assert(fell_back == 1);
    assert(cJSON_GetArraySize(cJSON_GetObjectItem(root, "backends")) == 5);
    cJSON_Delete(root);
}

static void test_backends_roundtrip(void)
{
    cJSON *root = NULL;
    cJSON *backends;
    cJSON *item;
    int fell_back = 0;
    char error[96];

    /* 写一个自定义 backends（含新预设） */
    root = cJSON_CreateObject();
    cJSON_AddNumberToObject(root, "version", 1);
    backends = cJSON_AddArrayToObject(root, "backends");
    item = cJSON_CreateObject();
    cJSON_AddStringToObject(item, "backend_id", "my_gw");
    cJSON_AddStringToObject(item, "label", "My Gateway");
    cJSON_AddStringToObject(item, "host", "10.0.2.2");
    cJSON_AddStringToObject(item, "path", "/v1/chat/completions");
    cJSON_AddStringToObject(item, "port", "8080");
    cJSON_AddStringToObject(item, "default_model", "qwen-plus");
    cJSON_AddNumberToObject(item, "default_timeout_ms", 30000);
    cJSON_AddItemToArray(backends, item);
    assert(smart_home_config_backends_save(root) == AGENT_OK);
    cJSON_Delete(root);

    /* 重载 → 读回自定义预设，不 fell_back */
    assert(smart_home_config_backends_load(&root, &fell_back, error,
                                           sizeof(error)) == AGENT_OK);
    assert(fell_back == 0);
    assert(cJSON_GetArraySize(cJSON_GetObjectItem(root, "backends")) == 1);
    cJSON_Delete(root);
}

static void test_backends_bad_version_falls_back(void)
{
    cJSON *root = NULL;
    int fell_back = 0;
    char error[96];
    FILE *file;

    /* 写入 version=99 → 拒绝并回退默认 */
    file = fopen(g_backends_path, "wb");
    assert(file != NULL);
    fputs("{\"version\":99,\"backends\":[]}", file);
    fclose(file);

    assert(smart_home_config_backends_load(&root, &fell_back, error,
                                           sizeof(error)) == AGENT_OK);
    assert(fell_back == 1);
    assert(root != NULL);
    cJSON_Delete(root);
}

static void test_backends_duplicate_id_falls_back(void)
{
    cJSON *root = NULL;
    int fell_back = 0;
    char error[96];
    FILE *file;

    /* 重复 backend_id → 校验失败 → 回退 */
    file = fopen(g_backends_path, "wb");
    assert(file != NULL);
    fputs("{\"version\":1,\"backends\":["
          "{\"backend_id\":\"a\",\"label\":\"A\",\"host\":\"h\","
          "\"path\":\"/v1\",\"port\":\"443\",\"default_model\":\"m\","
          "\"default_timeout_ms\":30000},"
          "{\"backend_id\":\"a\",\"label\":\"A2\",\"host\":\"h2\","
          "\"path\":\"/v1\",\"port\":\"443\",\"default_model\":\"m2\","
          "\"default_timeout_ms\":30000}]}", file);
    fclose(file);

    assert(smart_home_config_backends_load(&root, &fell_back, error,
                                           sizeof(error)) == AGENT_OK);
    assert(fell_back == 1);
    cJSON_Delete(root);
}

static void test_settings_roundtrip_and_fallback(void)
{
    cJSON *root = NULL;
    int fell_back = 0;
    char error[96];

    /* 缺失 → 回退 deepseek */
    assert(smart_home_config_settings_load(&root, &fell_back, error,
                                           sizeof(error)) == AGENT_OK);
    assert(fell_back == 1);
    assert(strcmp(cJSON_GetObjectItem(root, "active_backend_id")->valuestring,
                  "deepseek") == 0);
    cJSON_Delete(root);

    /* 写 kimi → 重载不 fell_back */
    root = cJSON_CreateObject();
    cJSON_AddNumberToObject(root, "version", 1);
    cJSON_AddStringToObject(root, "active_backend_id", "kimi");
    assert(smart_home_config_settings_save(root) == AGENT_OK);
    cJSON_Delete(root);

    assert(smart_home_config_settings_load(&root, &fell_back, error,
                                           sizeof(error)) == AGENT_OK);
    assert(fell_back == 0);
    assert(strcmp(cJSON_GetObjectItem(root, "active_backend_id")->valuestring,
                  "kimi") == 0);
    cJSON_Delete(root);
}

static void test_state_roundtrip(void)
{
    cJSON *root = NULL;
    int fell_back = 0;
    char error[96];

    /* 缺失 → 回退 3 个默认设备 */
    assert(smart_home_config_state_load(&root, &fell_back, error,
                                        sizeof(error)) == AGENT_OK);
    assert(fell_back == 1);
    assert(cJSON_GetArraySize(cJSON_GetObjectItem(root, "devices")) == 3);
    cJSON_Delete(root);

    /* 写一个设备 → 重载 */
    root = cJSON_CreateObject();
    cJSON_AddNumberToObject(root, "version", 1);
