int smart_home_config_state_save(const cJSON *root)
{
    smart_home_state_t state;
    int ret;

    if (!root) {
        return AGENT_ERROR_INVALID;
    }
    ret = check_version(root, NULL, 0);
    if (ret != AGENT_OK) {
        return ret;
