static int send_all(int fd, const void *payload, size_t length, uint64_t deadline_ms)
{
    const unsigned char *bytes = payload;
    size_t offset = 0u;

    while (offset < length) {
        ssize_t count;
        int rc = wait_fd(fd, POLLOUT, deadline_ms);

        if (rc != CADDONS_OK) {
            return rc;
        }
        count = send(fd, bytes + offset, length - offset, MSG_NOSIGNAL);
        if (count > 0) {
            offset += (size_t)count;
        } else if (count < 0 && (errno == EINTR || errno == EAGAIN || errno == EWOULDBLOCK)) {
            continue;
        } else {
            return CADDONS_ERR_NETWORK;
        }
    }
    return CADDONS_OK;
}

static int receive_exact(int fd, char *output, size_t length, uint64_t deadline_ms)
{
    size_t offset = 0u;

    while (offset < length) {
        ssize_t count;
        int rc = wait_fd(fd, POLLIN, deadline_ms);

        if (rc != CADDONS_OK) {
