/* ── 连接封装（明文 fd 或 TLS ctx） ── */

typedef struct {
    int fd;             /* 底层 socket（TLS 时为握手后的 fd） */
    ov_tls_ctx_t *tls;  /* NULL = 明文 */
} smh_conn_t;

/* 建立连接：is_tls 走 cAGENT ov_tls_connect，否则走 connect_socket */
static int smh_conn_open(smh_conn_t *conn,
                         const caddons_http_request_t *request,
                         uint64_t deadline_ms)
{
    char port_text[8];

    memset(conn, 0, sizeof(*conn));
    conn->fd = -1;

    if (!request->is_tls) {
        conn->fd = connect_socket(request->host, request->port, deadline_ms);
        return conn->fd >= 0 ? CADDONS_OK : CADDONS_ERR_NETWORK;
    }

    conn->tls = calloc(1, sizeof(*conn->tls));
    if (!conn->tls) {
        return CADDONS_ERR_NOMEM;
    }
    snprintf(port_text, sizeof(port_text), "%u", (unsigned int)request->port);
    if (ov_tls_connect(conn->tls, request->host, port_text,
                       (uint32_t)(deadline_ms ? deadline_ms / 1000u : 30u))
        != AGENT_OK) {
        ov_tls_ctx_free(conn->tls);
        free(conn->tls);
        conn->tls = NULL;
        return CADDONS_ERR_NETWORK;
    }
    conn->fd = conn->tls->net.fd;
    return CADDONS_OK;
}

/* 单次读：TLS 走 mbedtls_ssl_read（处理 WANT_READ），明文走 recv */
static ssize_t smh_conn_read_once(smh_conn_t *conn, void *buffer, size_t length,
                                  uint64_t deadline_ms)
{
    if (conn->tls) {
        for (;;) {
            int count = mbedtls_ssl_read(&conn->tls->ssl, buffer, length);

            if (count == MBEDTLS_ERR_SSL_WANT_READ) {
                if (wait_fd(conn->fd, POLLIN, deadline_ms) != CADDONS_OK) {
                    return -1;
                }
                continue;
            }
            if (count == MBEDTLS_ERR_SSL_WANT_WRITE) {
                if (wait_fd(conn->fd, POLLOUT, deadline_ms) != CADDONS_OK) {
                    return -1;
                }
                continue;
            }
            return count < 0 ? -1 : (ssize_t)count;
        }
    }
    return recv(conn->fd, buffer, length, 0);
}

/* 单次写：TLS 走 mbedtls_ssl_write，明文走 send */
static ssize_t smh_conn_write_once(smh_conn_t *conn, const void *buffer,
                                   size_t length, uint64_t deadline_ms)
{
    if (conn->tls) {
        for (;;) {
            int count = mbedtls_ssl_write(&conn->tls->ssl, buffer, length);

            if (count == MBEDTLS_ERR_SSL_WANT_WRITE) {
                if (wait_fd(conn->fd, POLLOUT, deadline_ms) != CADDONS_OK) {
                    return -1;
                }
                continue;
            }
            if (count == MBEDTLS_ERR_SSL_WANT_READ) {
                if (wait_fd(conn->fd, POLLIN, deadline_ms) != CADDONS_OK) {
                    return -1;
                }
                continue;
            }
            return count < 0 ? -1 : (ssize_t)count;
        }
    }
    return send(conn->fd, buffer, length, MSG_NOSIGNAL);
}

static void smh_conn_close(smh_conn_t *conn)
{
    if (conn->tls) {
        ov_tls_ctx_free(conn->tls);
        free(conn->tls);
        conn->tls = NULL;
    }
    if (conn->fd >= 0) {
        close(conn->fd);
        conn->fd = -1;
    }
}

