/* ── TLS context ────────────────────────────────────────────── */
/* ov_tls_ctx_t 不透明句柄声明在 runtime_openvela.h；完整定义在此。
 * ov_tls_connect / ov_tls_read / ov_tls_write / ov_tls_ctx_free
 * 供同固件应用层复用 TLS 连接。 */

struct ov_tls_ctx {
    mbedtls_ssl_context ssl;
    mbedtls_ssl_config cfg;
    mbedtls_net_context net;
    mbedtls_ctr_drbg_context ctr_drbg;
    mbedtls_entropy_context entropy;
};

ssize_t ov_tls_read(ov_tls_ctx_t *ctx, void *buffer, size_t length,
                    uint32_t timeout_ms)
{
    if (!ctx || !buffer) {
        errno = EINVAL;
        return -1;
    }
    for (;;) {
        int count = mbedtls_ssl_read(&ctx->ssl, buffer, length);

        if (count == MBEDTLS_ERR_SSL_WANT_READ) {
            if (timeout_ms == 0u) {
                continue;
            }
            if (ov_tls_wait_fd(ctx, POLLIN, timeout_ms) != 0) {
                errno = ETIMEDOUT;
                return -1;
            }
            continue;
        }
        if (count == MBEDTLS_ERR_SSL_WANT_WRITE) {
            if (ov_tls_wait_fd(ctx, POLLOUT, timeout_ms) != 0) {
                errno = ETIMEDOUT;
                return -1;
            }
            continue;
        }
        if (count < 0) {
            errno = EIO;
            return -1;
        }
        return (ssize_t)count;
    }
}

