/* discovery 线程：网络发现（TLS 握手 + initialize + tools/list）的唯一
 * 执行者。不持 agent_mutex，不触碰 agent registry；工具经 catalog diff
 * 与 mutation worker 进入注册表。收敛到 READY/FAILED 后退出。 */
static void *discovery_main(void *argument)
{
    smart_home_mcp_bridge_t *bridge = argument;
    int rc;

    rc = caddons_mcp_bridge_start(bridge->bridge);

    pthread_mutex_lock(&bridge->state_mutex);
    bridge->discovery_error = (rc == CADDONS_OK) ? 0 : rc;
    bridge->state = (rc == CADDONS_OK) ? SMART_HOME_MCP_STATE_READY
                                       : SMART_HOME_MCP_STATE_FAILED;
    pthread_mutex_unlock(&bridge->state_mutex);

    if (rc == CADDONS_OK) {
        syslog(LOG_INFO, "smart_home: MCP discovery succeeded\n");
    } else {
        syslog(LOG_ERR, "smart_home: MCP discovery failed: %d\n", rc);
    }
    return NULL;
}

static int start_discovery(smart_home_mcp_bridge_t *bridge)
{
    pthread_attr_t attributes;
    int rc;

    if (pthread_attr_init(&attributes) != 0) {
        return CADDONS_ERR_INTERNAL;
    }
#ifdef __NuttX__
    /* mbedTLS 握手 + 有界响应解析需要显式大栈，默认 pthread 栈不够。 */
    rc = pthread_attr_setstacksize(
        &attributes, CONFIG_SMART_HOME_MCP_BRIDGE_DISCOVERY_STACKSIZE);
    if (rc != 0) {
        pthread_attr_destroy(&attributes);
        return CADDONS_ERR_INVALID;
    }
#endif
    rc = pthread_create(&bridge->discovery_thread, &attributes,
                        discovery_main, bridge);
    pthread_attr_destroy(&attributes);
    if (rc != 0) {
        return CADDONS_ERR_INTERNAL;
    }
    bridge->discovery_started = true;
    return CADDONS_OK;
}

static void destroy_bridge(smart_home_mcp_bridge_t *bridge)
{
    if (!bridge) {
        return;
    }
    /* 先 join 可能仍在进行网络发现的 discovery 线程（有界：网络 I/O 带
     * monotonic deadline），再停止 bridge，避免释放后仍被使用。 */
    if (bridge->discovery_started) {
        pthread_join(bridge->discovery_thread, NULL);
    }
    if (bridge->bridge) {
        (void)caddons_mcp_bridge_stop(bridge->bridge);
    }
    if (bridge->state_mutex_ready) {
        pthread_mutex_lock(&bridge->state_mutex);
        bridge->stopping = true;

    config.catalog_changed_user_data = bridge;
    config.request_timeout_ms = 10000u;
    bridge->bridge = caddons_mcp_bridge_create(&config);
    if (!bridge->bridge) {
        rc = CADDONS_ERR_INVALID;
        goto fail;
    }
    /* 网络发现异步化：init 线程只做纯内存装配，TLS/initialize/tools/list
     * 由 discovery 线程执行，服务器慢或不可达不再阻塞 UI 启动。 */
    pthread_mutex_lock(&bridge->state_mutex);
    bridge->state = SMART_HOME_MCP_STATE_CONNECTING;
    bridge->discovery_error = 0;
    pthread_mutex_unlock(&bridge->state_mutex);
    rc = start_discovery(bridge);
    if (rc != CADDONS_OK) {
        goto fail;
    }
    *bridge_out = bridge;
    syslog(LOG_INFO, "smart_home: MCP discovery started: %s:%u%s\n",
           config.host, (unsigned int)config.port, config.path);
    secure_clear(&settings, sizeof(settings));
    return AGENT_OK;

fail:
    secure_clear(&settings, sizeof(settings));
    destroy_bridge(bridge);
    return caddons_error_to_agent(rc);
}

int smart_home_mcp_bridge_get_state(smart_home_mcp_bridge_t *bridge,
                                    smart_home_mcp_state_t *state,
                                    int *last_error)
{
    if (!bridge || !state) {
        return AGENT_ERROR_INVALID;
    }

    pthread_mutex_lock(&bridge->state_mutex);
    *state = bridge->state;
    if (last_error) {
        *last_error = bridge->discovery_error;
    }
    pthread_mutex_unlock(&bridge->state_mutex);
    return AGENT_OK;
}

int smart_home_mcp_bridge_wait_ready(smart_home_mcp_bridge_t *bridge,
                                     uint32_t timeout_ms)
{
    uint64_t deadline;
    smart_home_mcp_state_t state;

int smart_home_mcp_bridge_wait_ready(smart_home_mcp_bridge_t *bridge,
                                     uint32_t timeout_ms)
{
    uint64_t deadline;
    smart_home_mcp_state_t state;
    int last_error = 0;

    if (!bridge) {
        return AGENT_ERROR_INVALID;
    }

    deadline = monotonic_ms() + timeout_ms;
    for (;;) {
        (void)smart_home_mcp_bridge_get_state(bridge, &state, &last_error);
        if (state == SMART_HOME_MCP_STATE_READY) {
            return AGENT_OK;
        }
        if (state == SMART_HOME_MCP_STATE_FAILED) {
            return caddons_error_to_agent(last_error);
        }
        if (monotonic_ms() >= deadline) {
            return AGENT_ERROR_TIMEOUT;
        }
        usleep(20000);
    }
}
