static void *agent_worker_main(void *arg)
{
    agent_job_t *job = (agent_job_t *)arg;
    agent_done_t *done;

    if (!job) {
        return NULL;
    }

    done = (agent_done_t *)calloc(1, sizeof(*done));
    if (!done) {
        if (job->ui) {
            job->ui->request_inflight = 0;
        }
        free(job);
        return NULL;
    }

    done->ui = job->ui;
    done->ret = smart_home_agent_run(job->ui->app,
                                     job->input,
                                     done->output,
                                     sizeof(done->output));
    lv_async_call(agent_done_async_cb, done);
    free(job);
    return NULL;
}
